#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so the garbage collector does not purge it mid-game.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker was held in a raw pointer (UArenaScoreTracker* ScoreTracker) that is not a UPROPERTY, so the garbage collector could collect it. The packaged Shipping log shows 'LogGarbage: Collecting garbage: 412 objects purged' about a minute after start; the next goal then called AArenaGameMode::OnGoalScored -> UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18) on the dead object, causing EXCEPTION_ACCESS_VIOLATION. Fix: make ScoreTracker a UPROPERTY (TObjectPtr) in ArenaGameMode.h.",
  "no_colors_cause": "The color palette asset /Game/Data/Palettes/DA_Primary was never cooked into the packaged build: DefaultGame.ini had bCookAll=False and only cooked /Game/Maps/Arena and /Game/Data/Effects. At runtime LoadObject failed (log: 'Couldn't find file for package /Game/Data/Palettes/DA_Primary'), the palette was null and the HUD fell back to gray ('Palette is null, using fallback gray'). Fix: add /Game/Data/Palettes to DirectoriesToAlwaysCook in DefaultGame.ini."
}
